 readonly (ExpressionEntity | SpreadElement)[]\n\t): void {\n\t\tif (this.isReassigned || (this.init && context.includedCallArguments.has(this.init))) {\n\t\t\tfor (const arg of args) {\n\t\t\t\targ.include(context, false);\n\t\t\t}\n\t\t} else if (this.init) {\n\t\t\tcontext.includedCallArguments.add(this.init);\n\t\t\tthis.init.includeCallArguments(context, args);\n\t\t\tcontext.includedCallArguments.delete(this.init);\n\t\t}\n\t}\n\n\tmarkCalledFromTryStatement(): void {\n\t\tthis.calledFromTryStatement = true;\n\t}\n\n\tmarkInitializersForDeoptimization(): ExpressionEntity[] {\n\t\tif (this.additionalInitializers === null) {\n\t\t\tthis.additionalInitializers = this.init === null ? [] : [this.init];\n\t\t\tthis.init = UNKNOWN_EXPRESSION;\n\t\t\tthis.isReassigned = true;\n\t\t}\n\t\treturn this.additionalInitializers;\n\t}\n}\n","const chars = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_$';\nconst base = 64;\n\nexport function toBase64(num: number): string {\n\tlet outStr = '';\n\tdo {\n\t\tconst curDigit = num % base;\n\t\tnum = Math.floor(num / base);\n\t\toutStr = chars[curDigit] + outStr;\n\t} while (num !== 0);\n\treturn outStr;\n}\n","import RESERVED_NAMES from './RESERVED_NAMES';\nimport { toBase64 } from './base64';\n\nexport function getSafeName(baseName: string, usedNames: Set<string>): string {\n\tlet safeName = baseName;\n\tlet count = 1;\n\twhile (usedNames.has(safeName) || RESERVED_NAMES.has(safeName)) {\n\t\tsafeName = `${baseName}$${toBase64(count++)}`;\n\t}\n\tusedNames.add(safeName);\n\treturn safeName;\n}\n","import type { AstContext } from '../../Module';\nimport type Identifier from '../nodes/Identifier';\nimport type { ExpressionEntity } from '../nodes/shared/Expression';\nimport { UNDEFINED_EXPRESSION } from '../values';\nimport LocalVariable from '../variables/LocalVariable';\nimport type Variable from '../variables/Variable';\nimport type ChildScope from './ChildScope';\n\nexport default class Scope {\n\tchildren: ChildScope[] = [];\n\tvariables = new Map<string, Variable>();\n\n\taddDeclaration(\n\t\tidentifier: Identifier,\n\t\tcontext: AstContext,\n\t\tinit: ExpressionEntity | null,\n\t\t_isHoisted: boolean\n\t): LocalVariable {\n\t\tconst name = identifier.name;\n\t\tlet variable = this.variables.get(name) as LocalVariable;\n\t\tif (variable) {\n\t\t\tvariable.addDeclaration(identifier, init);\n\t\t} else {\n\t\t\tvariable = new LocalVariable(\n\t\t\t\tidentifier.name,\n\t\t\t\tidentifier,\n\t\t\t\tinit || UNDEFINED_EXPRESSION,\n\t\t\t\tcontext\n\t\t\t);\n\t\t\tthis.variables.set(name, variable);\n\t\t}\n\t\treturn variable;\n\t}\n\n\tcontains(name: string): boolean {\n\t\treturn this.variables.has(name);\n\t}\n\n\tfindVariable(_name: string): Variable {\n\t\tthrow new Error('Internal Error: findVariable needs to be implemented by a subclass');\n\t}\n}\n","import type { InternalModuleFormat } from '../../rollup/types';\nimport { getSafeName } from '../../utils/safeName';\nimport type ImportExpression from '../nodes/ImportExpression';\nimport type { ExpressionEntity } from '../nodes/shared/Expression';\nimport type Variable from '../variables/Variable';\nimport Scope from './Scope';\n\nexport default class ChildScope extends Scope {\n\treadonly accessedOutsideVariables = new Map<string, Variable>();\n\tparent: Scope;\n\tprivate declare accessedDynamicImports?: Set<ImportExpression>;\n\n\tconstructor(parent: Scope) {\n\t\tsuper();\n\t\tthis.parent = parent;\n\t\tparent.children.push(this);\n\t}\n\n\taddAccessedDynamicImport(importExpression: ImportExpression): void {\n\t\t(this.accessedDynamicImports || (this.accessedDynamicImports = new Set())).add(\n\t\t\timportExpression\n\t\t);\n\t\tif (this.parent instanceof ChildScope) {\n\t\t\tthis.parent.addAccessedDynamicImport(importExpression);\n\t\t}\n\t}\n\n\taddAccessedGlobals(\n\t\tglobals: readonly string[],\n\t\taccessedGlobalsByScope: Map<ChildScope, Set<string>>\n\t): void {\n\t\tconst accessedGlobals = accessedGlobalsByScope.get(this) || new Set();\n\t\tfor (const name of globals) {\n\t\t\taccessedGlobals.add(name);\n\t\t}\n\t\taccessedGlobalsByScope.set(this, accessedGlobals);\n\t\tif (this.parent instanceof ChildScope) {\n\t\t\tthis.parent.addAccessedGlobals(globals, accessedGlobalsByScope);\n\t\t}\n\t}\n\n\taddNamespaceMemberAccess(name: string, variable: Variable): void {\n\t\tthis.accessedOutsideVariables.set(name, variable);\n\t\t(this.parent as ChildScope).addNamespaceMemberAccess(name, variable);\n\t}\n\n\taddReturnExpression(expression: ExpressionEntity): void {\n\t\tthis.parent instanceof ChildScope && this.parent.addReturnExpression(expression);\n\t}\n\n\taddUsedOutsideNames(\n\t\tusedNames: Set<string>,\n\t\tformat: InternalModuleFormat,\n\t\texportNamesByVariable: ReadonlyMap<Variable, readonly string[]>,\n\t\taccessedGlobalsByScope: ReadonlyMap<ChildScope, ReadonlySet<string>>\n\t): void {\n\t\tfor (const variable of this.accessedOutsideVariables.values()) {\n\t\t\tif (variable.included) {\n\t\t\t\tusedNames.add(variable.getBaseVariableName());\n\t\t\t\tif (format === 'system' && exportNamesByVariable.has(variable)) {\n\t\t\t\t\tusedNames.add('exports');\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tconst accessedGlobals = accessedGlobalsByScope.get(this);\n\t\tif (accessedGlobals) {\n\t\t\tfor (const name of accessedGlobals) {\n\t\t\t\tusedNames.add(name);\n\t\t\t}\n\t\t}\n\t}\n\n\tcontains(name: string): boolean {\n\t\treturn this.variables.has(name) || this.parent.contains(name);\n\t}\n\n\tdeconflict(\n\t\tformat: InternalModuleFormat,\n\t\texportNamesByVariable: ReadonlyMap<Variable, readonly string[]>,\n\t\taccessedGlobalsByScope: ReadonlyMap<ChildScope, ReadonlySet<string>>\n\t): void {\n\t\tconst usedNames = new Set<string>();\n\t\tthis.addUsedOutsideNames(usedNames, format, exportNamesByVariable, accessedGlobalsByScope);\n\t\tif (this.accessedDynamicImports) {\n\t\t\tfor (const importExpression of this.accessedDynamicImports) {\n\t\t\t\tif (importExpression.inlineNamespace) {\n\t\t\t\t\tusedNames.add(importExpression.inlineNamespace.getBaseVariableName());\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (const [name, variable] of this.variables) {\n\t\t\tif (variable.included || variable.alwaysRendered) {\n\t\t\t\tvariable.setRenderNames(null, getSafeName(name, usedNames));\n\t\t\t}\n\t\t}\n\t\tfor (const scope of this.children) {\n\t\t\tscope.deconflict(format, exportNamesByVariable, accessedGlobalsByScope);\n\t\t}\n\t}\n\n\tfindLexicalBoundary(): ChildScope {\n\t\treturn (this.parent as ChildScope).findLexicalBoundary();\n\t}\n\n\tfindVariable(name: string): Variable {\n\t\tconst knownVariable = this.variables.get(name) || this.accessedOutsideVariables.get(name);\n\t\tif (knownVariable) {\n\t\t\treturn knownVariable;\n\t\t}\n\t\tconst variable = this.parent.findVariable(name);\n\t\tthis.accessedOutsideVariables.set(name, variable);\n\t\treturn variable;\n\t}\n}\n","import type { AstContext } from '../../Module';\nimport type { InclusionContext } from '../ExecutionContext';\nimport type Identifier from '../nodes/Identifier';\nimport SpreadElement from '../nodes/SpreadElement';\nimport { ExpressionEntity, UNKNOWN_EXPRESSION } from '../nodes/shared/Expression';\nimport LocalVariable from '../variables/LocalVariable';\nimport ChildScope from './ChildScope';\nimport type Scope from './Scope';\n\nexport default class ParameterScope extends ChildScope {\n\treadonly hoistedBodyVarScope: ChildScope;\n\n\tprotected parameters: readonly LocalVariable[][] = [];\n\tprivate context: AstContext;\n\tprivate hasRest = false;\n\n\tconstructor(parent: Scope, context: AstContext) {\n\t\tsuper(parent);\n\t\tthis.context = context;\n\t\tthis.hoistedBodyVarScope = new ChildScope(this);\n\t}\n\n\t/**\n\t * Adds a parameter to this scope. Parameters must be added in the correct\n\t * order, e.g. from left to right.\n\t */\n\taddParameterDeclaration(identifier: Identifier): LocalVariable {\n\t\tconst name = identifier.name;\n\t\tlet variable = this.hoistedBodyVarScope.variables.get(name) as LocalVariable;\n\t\tif (variable) {\n\t\t\tvariable.addDeclaration(identifier, null);\n\t\t} else {\n\t\t\tvariable = new LocalVariable(name, identifier, UNKNOWN_EXPRESSION, this.context);\n\t\t}\n\t\tthis.variables.set(name, variable);\n\t\treturn variable;\n\t}\n\n\taddParameterVariables(parameters: LocalVariable[][], hasRest: boolean): void {\n\t\tthis.parameters = parameters;\n\t\tfor (const parameterList of parameters) {\n\t\t\tfor (const parameter of parameterList) {\n\t\t\t\tparameter.alwaysRendered = true;\n\t\t\t}\n\t\t}\n\t\tthis.hasRest = hasRest;\n\t}\n\n\tincludeCallArguments(\n\t\tcontext: InclusionContext,\n\t\targs: readonly (ExpressionEntity | SpreadElement)[]\n\t): void {\n\t\tlet calledFromTryStatement = false;\n\t\tlet argIncluded = false;\n\t\tconst restParam = this.hasRest && this.parameters[this.parameters.length - 1];\n\t\tfor (const checkedArg of args) {\n\t\t\tif (checkedArg instanceof SpreadElement) {\n\t\t\t\tfor (const arg of args) {\n\t\t\t\t\targ.include(context, false);\n\t\t\t\t}\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tfor (let index = args.length - 1; index >= 0; index--) {\n\t\t\tconst paramVars = this.parameters[index] || restParam;\n\t\t\tconst arg = args[index];\n\t\t\tif (paramVars) {\n\t\t\t\tcalledFromTryStatement = false;\n\t\t\t\tif (paramVars.length === 0) {\n\t\t\t\t\t// handle empty destructuring\n\t\t\t\t\targIncluded = true;\n\t\t\t\t} else {\n\t\t\t\t\tfor (const variable of paramVars) {\n\t\t\t\t\t\tif (variable.included) {\n\t\t\t\t\t\t\targIncluded = true;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (variable.calledFromTryStatement) {\n\t\t\t\t\t\t\tcalledFromTryStatement = true;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (!argIncluded && arg.shouldBeIncluded(context)) {\n\t\t\t\targIncluded = true;\n\t\t\t}\n\t\t\tif (argIncluded) {\n\t\t\t\targ.include(context, calledFromTryStatement);\n\t\t\t}\n\t\t}\n\t}\n}\n","import { type ExpressionEntity, UNKNOWN_EXPRESSION } from '../nodes/shared/Expression';\nimport { UNKNOWN_PATH } from '../utils/PathTracker';\nimport ParameterScope from './ParameterScope';\n\nexport default class ReturnValueScope extends ParameterScope {\n\tprivate returnExpression: ExpressionEntity | null = null;\n\tprivate returnExpressions: ExpressionEntity[] = [];\n\n\taddReturnExpression(expression: ExpressionEntity): void {\n\t\tthis.returnExpressions.push(expression);\n\t}\n\n\tgetReturnExpression(): ExpressionEntity {\n\t\tif (this.returnExpression === null) this.updateReturnExpression();\n\t\treturn this.returnExpression!;\n\t}\n\n\tprivate updateReturnExpression() {\n\t\tif (this.returnExpressions.length === 1) {\n\t\t\tthis.returnExpression = this.returnExpressions[0];\n\t\t} else {\n\t\t\tthis.returnExpression = UNKNOWN_EXPRESSION;\n\t\t\tfor (const expression of this.returnExpressions) {\n\t\t\t\texpression.deoptimizePath(UNKNOWN_PATH);\n\t\t\t}\n\t\t}\n\t}\n}\n","//@ts-check\n/** @typedef { import('estree').Node} Node */\n/** @typedef {Node | {\n *   type: 'PropertyDefinition';\n *   computed: boolean;\n *   value: Node\n * }} NodeWithPropertyDefinition */\n\n/**\n *\n * @param {NodeWithPropertyDefinition} node\n * @param {NodeWithPropertyDefinition} parent\n * @returns boolean\n */\nexport default function is_reference (node, parent) {\n\tif (node.type === 'MemberExpression') {\n\t\treturn !node.computed && is_reference(node.object, node);\n\t}\n\n\tif (node.type === 'Identifier') {\n\t\tif (!parent) return true;\n\n\t\tswitch (parent.type) {\n\t\t\t// disregard `bar` in `foo.bar`\n\t\t\tcase 'MemberExpression': return parent.computed || node === parent.object;\n\n\t\t\t// disregard the `foo` in `class {foo(){}}` but keep it in `class {[foo](){}}`\n\t\t\tcase 'MethodDefinition': return parent.computed;\n\n\t\t\t// disregard the `foo` in `class {foo=bar}` but keep it in `class {[foo]=bar}` and `class {bar=foo}`\n\t\t\tcase 'PropertyDefinition': return parent.computed || node === parent.value;\n\n\t\t\t// disregard the `bar` in `{ bar