Globals;\n}\n\nexport function getGlobalAtPath(path: ObjectPath): ValueDescription | null {\n\tlet currentGlobal: GlobalDescription | null = knownGlobals;\n\tfor (const pathSegment of path) {\n\t\tif (typeof pathSegment !== 'string') {\n\t\t\treturn null;\n\t\t}\n\t\tcurrentGlobal = currentGlobal[pathSegment];\n\t\tif (!currentGlobal) {\n\t\t\treturn null;\n\t\t}\n\t}\n\treturn currentGlobal[ValueProperties];\n}\n","import { DeoptimizableEntity } from '../DeoptimizableEntity';\nimport { HasEffectsContext } from '../ExecutionContext';\nimport {\n\tINTERACTION_ACCESSED,\n\tINTERACTION_ASSIGNED,\n\tINTERACTION_CALLED,\n\tNodeInteraction\n} from '../NodeInteractions';\nimport {\n\tLiteralValueOrUnknown,\n\tUnknownTruthyValue,\n\tUnknownValue\n} from '../nodes/shared/Expression';\nimport { getGlobalAtPath } from '../nodes/shared/knownGlobals';\nimport type { ObjectPath } from '../utils/PathTracker';\nimport { PathTracker } from '../utils/PathTracker';\nimport Variable from './Variable';\n\nexport default class GlobalVariable extends Variable {\n\t// Ensure we use live-bindings for globals as we do not know if they have\n\t// been reassigned\n\tisReassigned = true;\n\n\tgetLiteralValueAtPath(\n\t\tpath: ObjectPath,\n\t\t_recursionTracker: PathTracker,\n\t\t_origin: DeoptimizableEntity\n\t): LiteralValueOrUnknown {\n\t\treturn getGlobalAtPath([this.name, ...path]) ? UnknownTruthyValue : UnknownValue;\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tswitch (interaction.type) {\n\t\t\tcase INTERACTION_ACCESSED:\n\t\t\t\tif (path.length === 0) {\n\t\t\t\t\t// Technically, \"undefined\" is a global variable of sorts\n\t\t\t\t\treturn this.name !== 'undefined' && !getGlobalAtPath([this.name]);\n\t\t\t\t}\n\t\t\t\treturn !getGlobalAtPath([this.name, ...path].slice(0, -1));\n\t\t\tcase INTERACTION_ASSIGNED:\n\t\t\t\treturn true;\n\t\t\tcase INTERACTION_CALLED: {\n\t\t\t\tconst globalAtPath = getGlobalAtPath([this.name, ...path]);\n\t\t\t\treturn !globalAtPath || globalAtPath.hasEffectsWhenCalled(interaction, context);\n\t\t\t}\n\t\t}\n\t}\n}\n","import isReference, { type NodeWithFieldDefinition } from 'is-reference';\nimport type MagicString from 'magic-string';\nimport type { NormalizedTreeshakingOptions } from '../../rollup/types';\nimport { BLANK } from '../../utils/blank';\nimport type { NodeRenderOptions, RenderOptions } from '../../utils/renderHelpers';\nimport type { DeoptimizableEntity } from '../DeoptimizableEntity';\nimport type { HasEffectsContext, InclusionContext } from '../ExecutionContext';\nimport type { NodeInteractionWithThisArg } from '../NodeInteractions';\nimport {\n\tINTERACTION_ACCESSED,\n\tINTERACTION_ASSIGNED,\n\tINTERACTION_CALLED,\n\tNODE_INTERACTION_UNKNOWN_ACCESS,\n\tNodeInteraction,\n\tNodeInteractionCalled\n} from '../NodeInteractions';\nimport type FunctionScope from '../scopes/FunctionScope';\nimport { EMPTY_PATH, type ObjectPath, type PathTracker } from '../utils/PathTracker';\nimport GlobalVariable from '../variables/GlobalVariable';\nimport LocalVariable from '../variables/LocalVariable';\nimport type Variable from '../variables/Variable';\nimport * as NodeType from './NodeType';\nimport type SpreadElement from './SpreadElement';\nimport {\n\ttype ExpressionEntity,\n\ttype LiteralValueOrUnknown,\n\tUNKNOWN_EXPRESSION\n} from './shared/Expression';\nimport { NodeBase } from './shared/Node';\nimport type { PatternNode } from './shared/Pattern';\n\nexport type IdentifierWithVariable = Identifier & { variable: Variable };\n\nconst tdzVariableKinds = {\n\t__proto__: null,\n\tclass: true,\n\tconst: true,\n\tlet: true,\n\tvar: true\n};\n\nexport default class Identifier extends NodeBase implements PatternNode {\n\tdeclare name: string;\n\tdeclare type: NodeType.tIdentifier;\n\tvariable: Variable | null = null;\n\tprivate isTDZAccess: boolean | null = null;\n\n\taddExportedVariables(\n\t\tvariables: Variable[],\n\t\texportNamesByVariable: ReadonlyMap<Variable, readonly string[]>\n\t): void {\n\t\tif (exportNamesByVariable.has(this.variable!)) {\n\t\t\tvariables.push(this.variable!);\n\t\t}\n\t}\n\n\tbind(): void {\n\t\tif (!this.variable && isReference(this, this.parent as NodeWithFieldDefinition)) {\n\t\t\tthis.variable = this.scope.findVariable(this.name);\n\t\t\tthis.variable.addReference(this);\n\t\t}\n\t}\n\n\tdeclare(kind: string, init: ExpressionEntity): LocalVariable[] {\n\t\tlet variable: LocalVariable;\n\t\tconst { treeshake } = this.context.options;\n\t\tswitch (kind) {\n\t\t\tcase 'var':\n\t\t\t\tvariable = this.scope.addDeclaration(this, this.context, init, true);\n\t\t\t\tif (treeshake && treeshake.correctVarValueBeforeDeclaration) {\n\t\t\t\t\t// Necessary to make sure the init is deoptimized. We cannot call deoptimizePath here.\n\t\t\t\t\tvariable.markInitializersForDeoptimization();\n\t\t\t\t}\n\t\t\t\tbreak;\n\t\t\tcase 'function':\n\t\t\t\t// in strict mode, functions are only hoisted within a scope but not across block scopes\n\t\t\t\tvariable = this.scope.addDeclaration(this, this.context, init, false);\n\t\t\t\tbreak;\n\t\t\tcase 'let':\n\t\t\tcase 'const':\n\t\t\tcase 'class':\n\t\t\t\tvariable = this.scope.addDeclaration(this, this.context, init, false);\n\t\t\t\tbreak;\n\t\t\tcase 'parameter':\n\t\t\t\tvariable = (this.scope as FunctionScope).addParameterDeclaration(this);\n\t\t\t\tbreak;\n\t\t\t/* istanbul ignore next */\n\t\t\tdefault:\n\t\t\t\t/* istanbul ignore next */\n\t\t\t\tthrow new Error(`Internal Error: Unexpected identifier kind ${kind}.`);\n\t\t}\n\t\tvariable.kind = kind;\n\t\treturn [(this.variable = variable)];\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tif (path.length === 0 && !this.scope.contains(this.name)) {\n\t\t\tthis.disallowImportReassignment();\n\t\t}\n\t\t// We keep conditional chaining because an unknown Node could have an\n\t\t// Identifier as property that might be deoptimized by default\n\t\tthis.variable?.deoptimizePath(path);\n\t}\n\n\tdeoptimizeThisOnInteractionAtPath(\n\t\tinteraction: NodeInteractionWithThisArg,\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker\n\t): void {\n\t\tthis.variable!.deoptimizeThisOnInteractionAtPath(interaction, path, recursionTracker);\n\t}\n\n\tgetLiteralValueAtPath(\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): LiteralValueOrUnknown {\n\t\treturn this.getVariableRespectingTDZ()!.getLiteralValueAtPath(path, recursionTracker, origin);\n\t}\n\n\tgetReturnExpressionWhenCalledAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteractionCalled,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): ExpressionEntity {\n\t\treturn this.getVariableRespectingTDZ()!.getReturnExpressionWhenCalledAtPath(\n\t\t\tpath,\n\t\t\tinteraction,\n\t\t\trecursionTracker,\n\t\t\torigin\n\t\t);\n\t}\n\n\thasEffects(context: HasEffectsContext): boolean {\n\t\tif (!this.deoptimized) this.applyDeoptimizations();\n\t\tif (this.isPossibleTDZ() && this.variable!.kind !== 'var') {\n\t\t\treturn true;\n\t\t}\n\t\treturn (\n\t\t\t(this.context.options.treeshake as NormalizedTreeshakingOptions).unknownGlobalSideEffects &&\n\t\t\tthis.variable instanceof GlobalVariable &&\n\t\t\tthis.variable.hasEffectsOnInteractionAtPath(\n\t\t\t\tEMPTY_PATH,\n\t\t\t\tNODE_INTERACTION_UNKNOWN_ACCESS,\n\t\t\t\tcontext\n\t\t\t)\n\t\t);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tswitch (interaction.type) {\n\t\t\tcase INTERACTION_ACCESSED:\n\t\t\t\treturn (\n\t\t\t\t\tthis.variable !== null &&\n\t\t\t\t\tthis.getVariableRespectingTDZ()!.hasEffectsOnInteractionAtPath(path, interaction, context)\n\t\t\t\t);\n\t\t\tcase INTERACTION_ASSIGNED:\n\t\t\t\treturn (\n\t\t\t\t\tpath.length > 0 ? this.getVariableRespectingTDZ() : this.variable\n\t\t\t\t)!.hasEffectsOnInteractionAtPath(path, interaction, context);\n\t\t\tcase INTERACTION_CALLED:\n\t\t\t\treturn this.getVariableRespectingTDZ()!.hasEffectsOnInteractionAtPath(\n\t\t\t\t\tpath,\n\t\t\t\t\tinteraction,\n\t\t\t\t\tcontext\n\t\t\t\t);\n\t\t}\n\t}\n\n\tinclude(): void {\n\t\tif (!this.deoptimized) this.applyDeoptimizations();\n\t\tif (!this.included) {\n\t\t\tthis.included = true;\n\t\t\tif (this.variable !== null) {\n\t\t\t\tthis.context.includeVariableInModule(this.variable);\n\t\t\t}\n\t\t}\n\t}\n\n\tincludeCallArguments(\n\t\tcontext: InclusionContext,\n\t\targs: readonly (ExpressionEntity | SpreadElement)[]\n\t): void {\n\t\tthis.variable!.includeCallArguments(context, args);\n\t}\n\n\tisPossibleTDZ(): boolean {\n\t\t// return cached value to avoid issues with the next tree-shaking pass\n\t\tif (this.isTDZAccess !== null) return this.isTDZAccess;\n\n\t\tif (\n\t\t\t!(this.variable instanceof LocalVariable) ||\n\t\t\t!this.variable.kind ||\n\t\t\t!(this.variable.kind in tdzVariableKinds)\n\t\t) {\n\t\t\treturn (this.isTDZAccess = false);\n\t\t}\n\n\t\tlet decl_id;\n\t\tif (\n\t\t\tthis.variable.declarations &&\n\t\t\tthis.variable.declarations.length === 1 &&\n\t\t\t(decl_id = this.variable.declarations[0] as any) &&\n\t\t\tthis.start < decl_id.start &&\n\t\t\tclosestParentFunctionOrProgram(this) === closestParentFunctionOrProgram(decl_id)\n\t\t) {\n\t\t\t// a variable accessed before its declaration\n\t\t\t// in the same function or at top level of module\n\t\t\treturn (this.isTDZAccess = true);\n\t\t}\n\n\t\tif (!this.variable.initReached) {\n\t\t\t// Either a const/let TDZ violation or\n\t\t\t// var use before declaration was encountered.\n\t\t\treturn (this.isTDZAccess = true);\n\t\t}\n\n\t\treturn (this.isTDZAccess = false);\n\t}\n\n\tmarkDeclarationReached(): void {\n\t\tthis.variable!.initReached = true;\n\t}\n\n\trender(\n\t\tcode: MagicString,\n\t\t{ snippets: { getPropertyAccess } }: RenderOptions,\n\t\t{ renderedParentType, isCalleeOfRenderedParent, isShorthandProperty }: NodeRenderOptions = BLANK\n\t): void {\n\t\tif (this.variable) {\n\t\t\tconst name = this.variable.getName(getPropertyAccess);\n\n\t\t\tif (name !== this.name) {\n\t\t\t\tcode.overwrite(this.start, this.end, name, {\n\t\t\t\t\tcontentOnly: true,\n\t\t\t\t\tstoreName: true\n\t\t\t\t});\n\t\t\t\tif (isShorthandProperty) {\n\t\t\t\t\tcode.prependRight(this.start, `${this.name}: `);\n\t\t\t\t}\n\t\t\t}\n\t\t\t// In strict mode, any variable named \"eval\" must be the actual \"eval\" function\n\t\t\tif (\n\t\t\t\tname === 'eval' &&\n\t\t\t\trenderedParentType === NodeType.CallExpression &&\n\t\t\t\tisCalleeOfRenderedParent\n\t\t\t) {\n\t\t\t\tcode.appendRight(this.start, '0, ');\n\t\t\t}\n\t\t}\n\t}\n\n\tprotected applyDeoptimizations(): void {\n\t\tthis.deoptimized = true;\n\t\tif (this.variable instanceof LocalVariable) {\n\t\t\tthis.variable.consolidateInitializers();\n\t\t\tthis.context.requestTreeshakingPass();\n\t\t}\n\t}\n\n\tprivate disallowImportReassignment(): never {\n\t\treturn this.context.error(\n\t\t\t{\n\t\t\t\tcode: 'ILLEGAL_REASSIGNMENT',\n\t\t\t\tmessage: `Illegal reassignment to import '${this.name}'`\n\t\t\t},\n\t\t\tthis.start\n\t\t);\n\t}\n\n\tprivate getVariableRespectingTDZ(): ExpressionEntity | null {\n\t\tif (this.isPossibleTDZ()) {\n\t\t\treturn UNKNOWN_EXPRESSION;\n\t\t}\n\t\treturn this.variable;\n\t}\n}\n\nfunction closestParentFunctionOrProgram(node: any): any {\n\twhile (node && !/^Program|Function/.test(node.type)) {\n\t\tnode = node.parent;\n\t}\n\t// one of: ArrowFunctionExpression, FunctionDeclaration, FunctionExpression or Program\n\treturn node;\n}\n","import type MagicString from 'magic-string';\nimport * as NodeType from '../ast/nodes/NodeType';\nimport type { Node } from '../ast/nodes/shared/Node';\n\nexport function treeshakeNode(node: Node, code: MagicString, start: number, end: number): void {\n\tcode.remove(start, end);\n\tif (node.annotations) {\n\t\tfor (const annotation of node.annotations) {\n\t\t\tif (annotation.start < start) {\n\t\t\t\tcode.remove(annotation.start, annotation.end);\n\t\t\t} else {\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t}\n}\n\nexport function removeAnnotations(node: Node, code: MagicString): void {\n\tif (!node.annotations && node.parent.type === NodeType.ExpressionStatement) {\n\t\tnode = node.parent as Node;\n\t}\n\tif (node.annotations) {\n\t\tfor (const annotation of node.annotations) {\n\t\t\tcode.remove(annotation.start, annotation.end);\n\t\t}\n\t}\n}\n","import type MagicString from 'magic-string';\nimport type { Node, StatementNode } from '../ast/nodes/shared/Node';\nimport type Variable from '../ast/variables/Variable';\nimport type { InternalModuleFormat } from '../rollup/types';\nimport type { PluginDriver } from './PluginDriver';\nimport type { GenerateCodeSnippets } from './generateCodeSnippets';\nimport { treeshakeNode } from './treeshakeNode';\n\nexport interface RenderOptions {\n\tdynamicImportFunction: string | undefined;\n\texportNamesByVariable: Map<Variable, string[]>;\n\tformat: InternalModuleFormat;\n\tfreeze: boolean;\n\tindent: string;\n\tnamespaceToStringTag: boolean;\n\toutputPluginDriver: PluginDriver;\n\tsnippets: GenerateCodeSnippets;\n}\n\nexport interface NodeRenderOptions {\n\tend?: number;\n\tisCalleeOfRenderedParent?: boolean;\n\tisNoStatement?: boolean;\n\tisShorthandProperty?: boolean;\n\tpreventASI?: boolean;\n\t/* Indicates if the direct parent of an element changed.\n\tNecessary for determining the \"this\" context of callees. */\n\trenderedParentType?: string;\n\t/* Indicates if the parent or ancestor surrounding an element has changed and what it changed to.\n\tNecessary for adding parentheses. */\n\trenderedSurroundingElement?: string;\n\tstart?: number;\n}\n\nexport const NO_SEMICOLON: NodeRenderOptions = { isNoStatement: true };\n\n// This assumes there are only white-space and comments between start and the string we are looking for\nexport function findFirstOccurrenceOutsideComment(\n\tcode: string,\n\tsearchString: string,\n\tstart = 0\n): nu