mport type { RenderOptions } from './renderHelpers';\n\nexport function getSystemExportStatement(\n\texportedVariables: readonly Variable[],\n\t{ exportNamesByVariable, snippets: { _, getObject, getPropertyAccess } }: RenderOptions,\n\tmodifier = ''\n): string {\n\tif (\n\t\texportedVariables.length === 1 &&\n\t\texportNamesByVariable.get(exportedVariables[0])!.length === 1\n\t) {\n\t\tconst variable = exportedVariables[0];\n\t\treturn `exports('${exportNamesByVariable.get(variable)}',${_}${variable.getName(\n\t\t\tgetPropertyAccess\n\t\t)}${modifier})`;\n\t} else {\n\t\tconst fields: [key: string, value: string][] = [];\n\t\tfor (const variable of exportedVariables) {\n\t\t\tfor (const exportName of exportNamesByVariable.get(variable)!) {\n\t\t\t\tfields.push([exportName, variable.getName(getPropertyAccess) + modifier]);\n\t\t\t}\n\t\t}\n\t\treturn `exports(${getObject(fields, { lineBreakIndent: null })})`;\n\t}\n}\n\nexport function renderSystemExportExpression(\n\texportedVariable: Variable,\n\texpressionStart: number,\n\texpressionEnd: number,\n\tcode: MagicString,\n\t{ exportNamesByVariable, snippets: { _ } }: RenderOptions\n): void {\n\tcode.prependRight(\n\t\texpressionStart,\n\t\t`exports('${exportNamesByVariable.get(exportedVariable)}',${_}`\n\t);\n\tcode.appendLeft(expressionEnd, ')');\n}\n\nexport function renderSystemExportFunction(\n\texportedVariables: readonly Variable[],\n\texpressionStart: number,\n\texpressionEnd: number,\n\tneedsParens: boolean | undefined,\n\tcode: MagicString,\n\toptions: RenderOptions\n): void {\n\tconst { _, getDirectReturnIifeLeft } = options.snippets;\n\tcode.prependRight(\n\t\texpressionStart,\n\t\tgetDirectReturnIifeLeft(\n\t\t\t['v'],\n\t\t\t`${getSystemExportStatement(exportedVariables, options)},${_}v`,\n\t\t\t{ needsArrowReturnParens: true, needsWrappedFunction: needsParens }\n\t\t)\n\t);\n\tcode.appendLeft(expressionEnd, ')');\n}\n\nexport function renderSystemExportSequenceAfterExpression(\n\texportedVariable: Variable,\n\texpressionStart: number,\n\texpressionEnd: number,\n\tneedsParens: boolean | undefined,\n\tcode: MagicString,\n\toptions: RenderOptions\n): void {\n\tconst { _, getPropertyAccess } = options.snippets;\n\tcode.appendLeft(\n\t\texpressionEnd,\n\t\t`,${_}${getSystemExportStatement([exportedVariable], options)},${_}${exportedVariable.getName(\n\t\t\tgetPropertyAccess\n\t\t)}`\n\t);\n\tif (needsParens) {\n\t\tcode.prependRight(expressionStart, '(');\n\t\tcode.appendLeft(expressionEnd, ')');\n\t}\n}\n\nexport function renderSystemExportSequenceBeforeExpression(\n\texportedVariable: Variable,\n\texpressionStart: number,\n\texpressionEnd: number,\n\tneedsParens: boolean | undefined,\n\tcode: MagicString,\n\toptions: RenderOptions,\n\tmodifier: string\n): void {\n\tconst { _ } = options.snippets;\n\tcode.prependRight(\n\t\texpressionStart,\n\t\t`${getSystemExportStatement([exportedVariable], options, modifier)},${_}`\n\t);\n\tif (needsParens) {\n\t\tcode.prependRight(expressionStart, '(');\n\t\tcode.appendLeft(expressionEnd, ')');\n\t}\n}\n","import type { HasEffectsContext } from '../ExecutionContext';\nimport { NodeInteractionAssigned } from '../NodeInteractions';\nimport { EMPTY_PATH, type ObjectPath } from '../utils/PathTracker';\nimport type LocalVariable from '../variables/LocalVariable';\nimport type Variable from '../variables/Variable';\nimport * as NodeType from './NodeType';\nimport type Property from './Property';\nimport type RestElement from './RestElement';\nimport type { ExpressionEntity } from './shared/Expression';\nimport { NodeBase } from './shared/Node';\nimport type { PatternNode } from './shared/Pattern';\n\nexport default class ObjectPattern extends NodeBase implements PatternNode {\n\tdeclare properties: readonly (Property | RestElement)[];\n\tdeclare type: NodeType.tObjectPattern;\n\n\taddExportedVariables(\n\t\tvariables: readonly Variable[],\n\t\texportNamesByVariable: ReadonlyMap<Variable, readonly string[]>\n\t): void {\n\t\tfor (const property of this.properties) {\n\t\t\tif (property.type === NodeType.Property) {\n\t\t\t\t(property.value as unknown as PatternNode).addExportedVariables(\n\t\t\t\t\tvariables,\n\t\t\t\t\texportNamesByVariable\n\t\t\t\t);\n\t\t\t} else {\n\t\t\t\tproperty.argument.addExportedVariables(variables, exportNamesByVariable);\n\t\t\t}\n\t\t}\n\t}\n\n\tdeclare(kind: string, init: ExpressionEntity): LocalVariable[] {\n\t\tconst variables: LocalVariable[] = [];\n\t\tfor (const property of this.properties) {\n\t\t\tvariables.push(...property.declare(kind, init));\n\t\t}\n\t\treturn variables;\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tif (path.length === 0) {\n\t\t\tfor (const property of this.properties) {\n\t\t\t\tproperty.deoptimizePath(path);\n\t\t\t}\n\t\t}\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\t// At the moment, this is only triggered for assignment left-hand sides,\n\t\t// where the path is empty\n\t\t_path: ObjectPath,\n\t\tinteraction: NodeInteractionAssigned,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tfor (const property of this.properties) {\n\t\t\tif (property.hasEffectsOnInteractionAtPath(EMPTY_PATH, interaction, context)) return true;\n\t\t}\n\t\treturn false;\n\t}\n\n\tmarkDeclarationReached(): void {\n\t\tfor (const property of this.properties) {\n\t\t\tproperty.markDeclarationReached();\n\t\t}\n\t}\n}\n","import type { AstContext } from '../../Module';\nimport { INTERACTION_ACCESSED, NodeInteraction } from '../NodeInteractions';\nimport { UNKNOWN_EXPRESSION } from '../nodes/shared/Expression';\nimport { ObjectPath } from '../utils/PathTracker';\nimport LocalVariable from './LocalVariable';\n\nexport default class ArgumentsVariable extends LocalVariable {\n\tconstructor(context: AstContext) {\n\t\tsuper('arguments', null, UNKNOWN_EXPRESSION, context);\n\t}\n\n\thasEffectsOnInteractionAtPath(path: ObjectPath, { type }: NodeInteraction): boolean {\n\t\treturn type !== INTERACTION_ACCESSED || path.length > 1;\n\t}\n}\n","import type { AstContext } from '../../Module';\nimport type { HasEffectsContext } from '../ExecutionContext';\nimport type { NodeInteraction, NodeInteractionWithThisArg } from '../NodeInteractions';\nimport { type ExpressionEntity, UNKNOWN_EXPRESSION } from '../nodes/shared/Expression';\nimport {\n\tDiscriminatedPathTracker,\n\ttype ObjectPath,\n\tSHARED_RECURSION_TRACKER\n} from '../utils/PathTracker';\nimport LocalVariable from './LocalVariable';\n\ninterface ThisDeoptimizationInteraction {\n\tinteraction: NodeInteractionWithThisArg;\n\tpath: ObjectPath;\n}\n\nexport default class ThisVariable extends LocalVariable {\n\tprivate readonly deoptimizedPaths: ObjectPath[] = [];\n\tprivate readonly entitiesToBeDeoptimized = new Set<ExpressionEntity>();\n\tprivate readonly thisDeoptimizationList: ThisDeoptimizationInteraction[] = [];\n\tprivate readonly thisDeoptimizations = new DiscriminatedPathTracker();\n\n\tconstructor(context: AstContext) {\n\t\tsuper('this', null, null, context);\n\t}\n\n\taddEntityToBeDeoptimized(entity: ExpressionEntity): void {\n\t\tfor (const path of this.deoptimizedPaths) {\n\t\t\tentity.deoptimizePath(path);\n\t\t}\n\t\tfor (const { interaction, path } of this.thisDeoptimizationList) {\n\t\t\tentity.deoptimizeThisOnInteractionAtPath(interaction, path, SHARED_RECURSION_TRACKER);\n\t\t}\n\t\tthis.entitiesToBeDeoptimized.add(entity);\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tif (\n\t\t\tpath.length === 0 ||\n\t\t\tthis.deoptimizationTracker.trackEntityAtPathAndGetIfTracked(path, this)\n\t\t) {\n\t\t\treturn;\n\t\t}\n\t\tthis.deoptimizedPaths.push(path);\n\t\tfor (const entity of this.entitiesToBeDeoptimized) {\n\t\t\tentity.deoptimizePath(path);\n\t\t}\n\t}\n\n\tdeoptimizeThisOnInteractionAtPath(\n\t\tinteraction: NodeInteractionWithThisArg,\n\t\tpath: ObjectPath\n\t): void {\n\t\tconst thisDeoptimization: ThisDeoptimizationInteraction = {\n\t\t\tinteraction,\n\t\t\tpath\n\t\t};\n\t\tif (\n\t\t\t!this.thisDeoptimizations.trackEntityAtPathAndGetIfTracked(\n\t\t\t\tpath,\n\t\t\t\tinteraction.type,\n\t\t\t\tinteraction.thisArg\n\t\t\t)\n\t\t) {\n\t\t\tfor (const entity of this.entitiesToBeDeoptimized) {\n\t\t\t\tentity.deoptimizeThisOnInteractionAtPath(interaction, path, SHARED_RECURSION_TRACKER);\n\t\t\t}\n\t\t\tthis.thisDeoptimizationList.push(thisDeoptimization);\n\t\t}\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\treturn (\n\t\t\tthis.getInit(context).hasEffectsOnInteractionAtPath(path, interaction, context) ||\n\t\t\tsuper.hasEffectsOnInteractionAtPath(path, interaction, context)\n\t\t);\n\t}\n\n\tprivate getInit(context: HasEffectsContext): ExpressionEntity {\n\t\treturn context.replacedVariableInits.get(this) || UNKNOWN_EXPRESSION;\n\t}\n}\n","import type { AstContext } from '../../Module';\nimport type { InclusionContext } from '../ExecutionContext';\nimport type SpreadElement from '../nodes/SpreadElement';\nimport { ExpressionEntity } from '../nodes/shared/Expression';\nimport ArgumentsVariable from '../variables/ArgumentsVariable';\nimport ThisVariable from '../variables/ThisVariable';\nimport type ChildScope from './ChildScope';\nimport ReturnValueScope from './ReturnValueScope';\n\nexport default class FunctionScope extends ReturnValueScope {\n\treadonly argumentsVariable: ArgumentsVariable;\n\treadonly thisVariable: ThisVariable;\n\n\tconstructor(parent: ChildScope, context: AstContext) {\n\t\tsuper(parent, context);\n\t\tthis.variables.set('arguments', (this.argumentsVariable = new ArgumentsVariable(context)));\n\t\tthis.variables.set('this', (this.thisVariable = new ThisVariable(context)));\n\t}\n\n\tfindLexicalBoundary(): ChildScope {\n\t\treturn this;\n\t}\n\n\tincludeCallArguments(\n\t\tcontext: InclusionContext,\n\t\targs: readonly (ExpressionEntity | SpreadElement)[]\n\t): void {\n\t\tsuper.includeCallArguments(context, args);\n\t\tif (this.argumentsVariable.included) {\n\t\t\tfor (const arg of args) {\n\t\t\t\tif (!arg.included) {\n\t\t\t\t\targ.include(context, false);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n}\n","import { type HasEffectsContext, type InclusionContext } from '../../ExecutionContext';\nimport {\n\tINTERACTION_CALLED,\n\tNodeInteraction,\n\tNodeInteractionWithThisArg\n} from '../../NodeInteractions';\nimport FunctionScope from '../../scopes/FunctionScope';\nimport { type ObjectPath, PathTracker } from '../../utils/PathTracker';\nimport BlockStatement from '../BlockStatement';\nimport Identifier, { type IdentifierWithVariable } from '../Identifier';\nimport { UNKNOWN_EXPRESSION } from './Expression';\nimport FunctionBase from './FunctionBase';\nimport { type IncludeChildren } from './Node';\nimport { ObjectEntity } from './ObjectEntity';\nimport { OBJECT_PROTOTYPE } from './ObjectPrototype';\nimport type { PatternNode } from './Pattern';\n\nexport default class FunctionNode extends FunctionBase {\n\tdeclare async: boolean;\n\tdeclare body: BlockStatement;\n\tdeclare id: IdentifierWithVariable | null;\n\tdeclare params: readonly PatternNode[];\n\tdeclare preventChildBlockScope: true;\n\tdeclare scope: FunctionScope;\n\tprotected objectEntity: ObjectEntity | null = null;\n\n\tcreateScope(parentScope: FunctionScope): void {\n\t\tthis.scope = new FunctionScope(parentScope, this.context);\n\t}\n\n\tdeoptimizeThisOnInteractionAtPath(\n\t\tinteraction: NodeInteractionWithThisArg,\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker\n\t): void {\n\t\tsuper.deoptimizeThisOnInteractionAtPath(interaction, path, recursionTracker);\n\t\tif (interaction.type === INTERACTION_CALLED && path.length === 0) {\n\t\t\tthis.scope.thisVariable.addEntityToBeDeoptimized(interaction.thisArg);\n\t\t}\n\t}\n\n\thasEffects(context: HasEffectsContext): boolean {\n\t\tif (!this.deoptimized) this.applyDeoptimizations();\n\t\treturn !!this.id?.hasEffects(context);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tif (super.hasEffectsOnInteractionAtPath(path, interaction, context)) return true;\n\t\tif (interaction.type === INTERACTION_CALLED) {\n\t\t\tconst thisInit = context.replacedVariableInits.get(this.scope.thisVariable);\n\t\t\tcontext.replacedVariableInits.set(\n\t\t\t\tthis.scope.thisVariable,\n\t\t\t\tinteraction.withNew\n\t\t\t\t\t? new ObjectEntity(Object.create(null), OBJECT_PROTOTYPE)\n\t\t\t\t\t: UNKNOWN_EXPRESSION\n\t\t\t);\n\t\t\tconst { brokenFlow, ignore } = context;\n\t\t\tcontext.ignore = {\n\t\t\t\tbreaks: false,\n\t\t\t\tcontinues: false,\n\t\t\t\tlabels: new Set(),\n\t\t\t\treturnYield: true\n\t\t\t};\n\t\t\tif (this.body.hasEffects(context)) return true;\n\t\t\tcontext.brokenFlow = brokenFlow;\n\t\t\tif (thisInit) {\n\t\t\t\tcontext.replacedVariableInits.set(this.scope.thisVariable, thisInit);\n\t\t\t} else {\n\t\t\t\tcontext.replacedVariableInits.delete(this.scope.thisVariable);\n\t\t\t}\n\t\t\tcontext.ignore = ignore;\n\t\t}\n\t\treturn false;\n\t}\n\n\tinclude(context: InclusionContext, includeChildrenRecursively: IncludeChildren): void {\n\t\tsuper.include(context, includeChildrenRecursively);\n\t\tthis.id?.include();\n\t\tconst hasArguments = this.scope.argumentsVariable.included;\n\t\tfor (const param of this.params) {\n\t\t\tif (!(param instanceof Identifier) || hasArguments) {\n\t\t\t\tparam.include(context, includeChildrenRecursively);\n\t\t\t}\n\t\t}\n\t}\n\n\tinitialise(): void {\n\t\tsuper.initialise();\n\t\tthis.id?.declare('function', this);\n\t}\n\n\tprotected getObjectEntity(): ObjectEntity {\n\t\tif (this.objectEntity !== null) {\n\t\t\treturn this.objectEntity;\n\t\t}\n\t\treturn (this.objectEntity = new ObjectEntity(\n\t\t\t[\n\t\t\t\t{\n\t\t\t\t\tkey: 'prototype',\n\t\t\t\t\tkind: 'init',\n\t\t\t\t\tproperty: new ObjectEntity([], OBJECT_PROTOTYPE)\n\t\t\t\t}\n\t\t\t],\n\t\t\tOBJECT_PROTOTYPE\n\t\t));\n\t}\n}\n","import type MagicString from 'magic-string';\nimport { BLANK } from '..