this.accessedValue = UNKNOWN_EXPRESSION;\n\t\t\t\treturn (this.accessedValue = this.value.getReturnExpressionWhenCalledAtPath(\n\t\t\t\t\tEMPTY_PATH,\n\t\t\t\t\tNODE_INTERACTION_UNKNOWN_CALL,\n\t\t\t\t\tSHARED_RECURSION_TRACKER,\n\t\t\t\t\tthis\n\t\t\t\t));\n\t\t\t} else {\n\t\t\t\treturn (this.accessedValue = this.value);\n\t\t\t}\n\t\t}\n\t\treturn this.accessedValue;\n\t}\n}\n","import type FunctionExpression from './FunctionExpression';\nimport type * as NodeType from './NodeType';\nimport type PrivateIdentifier from './PrivateIdentifier';\nimport MethodBase from './shared/MethodBase';\nimport type { ExpressionNode } from './shared/Node';\n\nexport default class MethodDefinition extends MethodBase {\n\tdeclare key: ExpressionNode | PrivateIdentifier;\n\tdeclare kind: 'constructor' | 'method' | 'get' | 'set';\n\tdeclare static: boolean;\n\tdeclare type: NodeType.tMethodDefinition;\n\tdeclare value: FunctionExpression;\n\n\tprotected applyDeoptimizations() {}\n}\n","import type { DeoptimizableEntity } from '../../DeoptimizableEntity';\nimport type { HasEffectsContext } from '../../ExecutionContext';\nimport type { NodeInteractionWithThisArg } from '../../NodeInteractions';\nimport { NodeInteraction, NodeInteractionCalled } from '../../NodeInteractions';\nimport type { ObjectPath, PathTracker } from '../../utils/PathTracker';\nimport { ExpressionEntity, type LiteralValueOrUnknown } from './Expression';\n\nexport class ObjectMember extends ExpressionEntity {\n\tconstructor(private readonly object: ExpressionEntity, private readonly key: string) {\n\t\tsuper();\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tthis.object.deoptimizePath([this.key, ...path]);\n\t}\n\n\tdeoptimizeThisOnInteractionAtPath(\n\t\tinteraction: NodeInteractionWithThisArg,\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker\n\t): void {\n\t\tthis.object.deoptimizeThisOnInteractionAtPath(\n\t\t\tinteraction,\n\t\t\t[this.key, ...path],\n\t\t\trecursionTracker\n\t\t);\n\t}\n\n\tgetLiteralValueAtPath(\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): LiteralValueOrUnknown {\n\t\treturn this.object.getLiteralValueAtPath([this.key, ...path], recursionTracker, origin);\n\t}\n\n\tgetReturnExpressionWhenCalledAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteractionCalled,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): ExpressionEntity {\n\t\treturn this.object.getReturnExpressionWhenCalledAtPath(\n\t\t\t[this.key, ...path],\n\t\t\tinteraction,\n\t\t\trecursionTracker,\n\t\t\torigin\n\t\t);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\treturn this.object.hasEffectsOnInteractionAtPath([this.key, ...path], interaction, context);\n\t}\n}\n","import type { DeoptimizableEntity } from '../../DeoptimizableEntity';\nimport type { HasEffectsContext, InclusionContext } from '../../ExecutionContext';\nimport {\n\tINTERACTION_CALLED,\n\tNodeInteraction,\n\tNodeInteractionCalled,\n\tNodeInteractionWithThisArg\n} from '../../NodeInteractions';\nimport ChildScope from '../../scopes/ChildScope';\nimport type Scope from '../../scopes/Scope';\nimport {\n\tEMPTY_PATH,\n\ttype ObjectPath,\n\ttype PathTracker,\n\tSHARED_RECURSION_TRACKER,\n\tUNKNOWN_PATH,\n\tUnknownKey\n} from '../../utils/PathTracker';\nimport type ClassBody from '../ClassBody';\nimport Identifier from '../Identifier';\nimport type Literal from '../Literal';\nimport MethodDefinition from '../MethodDefinition';\nimport { type ExpressionEntity, type LiteralValueOrUnknown } from './Expression';\nimport { type ExpressionNode, type IncludeChildren, NodeBase } from './Node';\nimport { ObjectEntity, type ObjectProperty } from './ObjectEntity';\nimport { ObjectMember } from './ObjectMember';\nimport { OBJECT_PROTOTYPE } from './ObjectPrototype';\n\nexport default class ClassNode extends NodeBase implements DeoptimizableEntity {\n\tdeclare body: ClassBody;\n\tdeclare id: Identifier | null;\n\tdeclare superClass: ExpressionNode | null;\n\tprivate declare classConstructor: MethodDefinition | null;\n\tprivate objectEntity: ObjectEntity | null = null;\n\n\tcreateScope(parentScope: Scope): void {\n\t\tthis.scope = new ChildScope(parentScope);\n\t}\n\n\tdeoptimizeCache(): void {\n\t\tthis.getObjectEntity().deoptimizeAllProperties();\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tthis.getObjectEntity().deoptimizePath(path);\n\t}\n\n\tdeoptimizeThisOnInteractionAtPath(\n\t\tinteraction: NodeInteractionWithThisArg,\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker\n\t): void {\n\t\tthis.getObjectEntity().deoptimizeThisOnInteractionAtPath(interaction, path, recursionTracker);\n\t}\n\n\tgetLiteralValueAtPath(\n\t\tpath: ObjectPath,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): LiteralValueOrUnknown {\n\t\treturn this.getObjectEntity().getLiteralValueAtPath(path, recursionTracker, origin);\n\t}\n\n\tgetReturnExpressionWhenCalledAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteractionCalled,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): ExpressionEntity {\n\t\treturn this.getObjectEntity().getReturnExpressionWhenCalledAtPath(\n\t\t\tpath,\n\t\t\tinteraction,\n\t\t\trecursionTracker,\n\t\t\torigin\n\t\t);\n\t}\n\n\thasEffects(context: HasEffectsContext): boolean {\n\t\tif (!this.deoptimized) this.applyDeoptimizations();\n\t\tconst initEffect = this.superClass?.hasEffects(context) || this.body.hasEffects(context);\n\t\tthis.id?.markDeclarationReached();\n\t\treturn initEffect || super.hasEffects(context);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tif (interaction.type === INTERACTION_CALLED && path.length === 0) {\n\t\t\treturn (\n\t\t\t\t!interaction.withNew ||\n\t\t\t\t(this.classConstructor !== null\n\t\t\t\t\t? this.classConstructor.hasEffectsOnInteractionAtPath(path, interaction, context)\n\t\t\t\t\t: this.superClass?.hasEffectsOnInteractionAtPath(path, interaction, context)) ||\n\t\t\t\tfalse\n\t\t\t);\n\t\t} else {\n\t\t\treturn this.getObjectEntity().hasEffectsOnInteractionAtPath(path, interaction, context);\n\t\t}\n\t}\n\n\tinclude(context: InclusionContext, includeChildrenRecursively: IncludeChildren): void {\n\t\tif (!this.deoptimized) this.applyDeoptimizations();\n\t\tthis.included = true;\n\t\tthis.superClass?.include(context, includeChildrenRecursively);\n\t\tthis.body.include(context, includeChildrenRecursively);\n\t\tif (this.id) {\n\t\t\tthis.id.markDeclarationReached();\n\t\t\tthis.id.include();\n\t\t}\n\t}\n\n\tinitialise(): void {\n\t\tthis.id?.declare('class', this);\n\t\tfor (const method of this.body.body) {\n\t\t\tif (method instanceof MethodDefinition && method.kind === 'constructor') {\n\t\t\t\tthis.classConstructor = method;\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tthis.classConstructor = null;\n\t}\n\n\tprotected applyDeoptimizations(): void {\n\t\tthis.deoptimized = true;\n\t\tfor (const definition of this.body.body) {\n\t\t\tif (\n\t\t\t\t!(\n\t\t\t\t\tdefinition.static ||\n\t\t\t\t\t(definition instanceof MethodDefinition && definition.kind === 'constructor')\n\t\t\t\t)\n\t\t\t) {\n\t\t\t\t// Calls to methods are not tracked, ensure that the return value is deoptimized\n\t\t\t\tdefinition.deoptimizePath(UNKNOWN_PATH);\n\t\t\t}\n\t\t}\n\t\tthis.context.requestTreeshakingPass();\n\t}\n\n\tprivate getObjectEntity(): ObjectEntity {\n\t\tif (this.objectEntity !== null) {\n\t\t\treturn this.objectEntity;\n\t\t}\n\t\tconst staticProperties: ObjectProperty[] = [];\n\t\tconst dynamicMethods: ObjectProperty[] = [];\n\t\tfor (const definition of this.body.body) {\n\t\t\tconst properties = definition.static ? staticProperties : dynamicMethods;\n\t\t\tconst definitionKind = (definition as MethodDefinition | { kind: undefined }).kind;\n\t\t\t// Note that class fields do not end up on the prototype\n\t\t\tif (properties === dynamicMethods && !definitionKind) continue;\n\t\t\tconst kind = definitionKind === 'set' || definitionKind === 'get' ? definitionKind : 'init';\n\t\t\tlet key: string;\n\t\t\tif (definition.computed) {\n\t\t\t\tconst keyValue = definition.key.getLiteralValueAtPath(\n\t\t\t\t\tEMPTY_PATH,\n\t\t\t\t\tSHARED_RECURSION_TRACKER,\n\t\t\t\t\tthis\n\t\t\t\t);\n\t\t\t\tif (typeof keyValue === 'symbol') {\n\t\t\t\t\tproperties.push({ key: UnknownKey, kind, property: definition });\n\t\t\t\t\tcontinue;\n\t\t\t\t} else {\n\t\t\t\t\tkey = String(keyValue);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tkey =\n\t\t\t\t\tdefinition.key instanceof Identifier\n\t\t\t\t\t\t? definition.key.name\n\t\t\t\t\t\t: String((definition.key as Literal).value);\n\t\t\t}\n\t\t\tproperties.push({ key, kind, property: definition });\n\t\t}\n\t\tstaticProperties.unshift({\n\t\t\tkey: 'prototype',\n\t\t\tkind: 'init',\n\t\t\tproperty: new ObjectEntity(\n\t\t\t\tdynamicMethods,\n\t\t\t\tthis.superClass ? new ObjectMember(this.superClass, 'prototype') : OBJECT_PROTOTYPE\n\t\t\t)\n\t\t});\n\t\treturn (this.objectEntity = new ObjectEntity(\n\t\t\tstaticProperties,\n\t\t\tthis.superClass || OBJECT_PROTOTYPE\n\t\t));\n\t}\n}\n","import type MagicString from 'magic-string';\nimport type { RenderOptions } from '../../utils/renderHelpers';\nimport { getSystemExportStatement } from '../../utils/systemJsRendering';\nimport type ChildScope from '../scopes/ChildScope';\nimport Identifier, { type IdentifierWithVariable } from './Identifier';\nimport type * as NodeType from './NodeType';\nimport ClassNode from './shared/ClassNode';\nimport type { GenericEsTreeNode } from './shared/Node';\n\nexport default class ClassDeclaration extends ClassNode {\n\tdeclare id: IdentifierWithVariable | null;\n\tdeclare type: NodeType.tClassDeclaration;\n\n\tinitialise(): void {\n\t\tsuper.initialise();\n\t\tif (this.id !== null) {\n\t\t\tthis.id.variable.isId = true;\n\t\t}\n\t}\n\n\tparseNode(esTreeNode: GenericEsTreeNode): void {\n\t\tif (esTreeNode.id !== null) {\n\t\t\tthis.id = new Identifier(\n\t\t\t\tesTreeNode.id,\n\t\t\t\tthis,\n\t\t\t\tthis.scope.parent as ChildScope\n\t\t\t) as IdentifierWithVariable;\n\t\t}\n\t\tsuper.parseNode(esTreeNode);\n\t}\n\n\trender(code: MagicString, options: RenderOptions): void {\n\t\tconst {\n\t\t\texportNamesByVariable,\n\t\t\tformat,\n\t\t\tsnippets: { _ }\n\t\t} = options;\n\t\tif (format === 'system' && this.id && exportNamesByVariable.has(this.id.variable)) {\n\t\t\tcode.appendLeft(this.end, `${_}${getSystemExportStatement([this.id.variable], options)};`);\n\t\t}\n\t\tsuper.render(code, options);\n\t}\n}\n","import type { DeoptimizableEntity } from '../../DeoptimizableEntity';\nimport type { HasEffectsContext } from '../../ExecutionContext';\nimport { NodeInteraction, NodeInteractionCalled } from '../../NodeInteractions';\nimport type { ObjectPath, PathTracker } from '../../utils/PathTracker';\nimport { ExpressionEntity } from './Expression';\n\nexport class MultiExpression extends ExpressionEntity {\n\tincluded = false;\n\n\tconstructor(private expressions: readonly ExpressionEntity[]) {\n\t\tsuper();\n\t}\n\n\tdeoptimizePath(path: ObjectPath): void {\n\t\tfor (const expression of this.expressions) {\n\t\t\texpression.deoptimizePath(path);\n\t\t}\n\t}\n\n\tgetReturnExpressionWhenCalledAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteractionCalled,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): ExpressionEntity {\n\t\treturn new MultiExpression(\n\t\t\tthis.expressions.map(expression =>\n\t\t\t\texpression.getReturnExpressionWhenCalledAtPath(path, interaction, recursionTracker, origin)\n\t\t\t)\n\t\t);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tfor (const expression of this.expressions) {\n\t\t\tif (expression.hasEffectsOnInteractionAtPath(path, interaction, context)) return true;\n\t\t}\n\t\treturn false;\n\t}\n}\n","import type MagicString from 'magic-string';\nimport type { NodeRenderOptions, RenderOptions } from '../../utils/renderHelpers';\nimport type Identifier from './Identifier';\nimport type Literal from './Literal';\nimport type * as NodeType from './NodeType';\nimport { NodeBase } from './shared/Node';\n\nexport default class ExportAllDeclaration extends NodeBase {\n\tdeclare exported: Identifier | null;\n\tdeclare needsBoundaries: true;\n\tdeclare source: Literal<string>;\n\tdeclare type: NodeType.tExportAllDeclaration;\n\n\thasEffects(): boolean {\n\t\treturn false;\n\t}\n\n\tinitialise(): void {\n\t\tthis.context.addExport(this);\n\t}\n\n\trender(code: MagicString, _options: RenderOptions, nodeRenderOptions?: NodeRenderOptions): void {\n\t\tcode.remove(nodeRenderOptions!.start!, nodeRenderOptions!.end!);\n\t}\n\n\tprotected applyDeoptimizations() {}\n}\n\nExportAllDeclaration.prototype.needsBoundaries = true;\n","import type ChildScope from '../scopes/ChildScope';\nimport Identifier, { type IdentifierWithVariable } from './Identifier';\nimport type * as NodeType from './NodeType';\nimport FunctionNode from './shared/FunctionNode';\nimport type { GenericEsTreeNode } from './shared/Node';\n\nexport default class FunctionDeclaration extends FunctionNode {\n\tdeclare type: NodeType.tFunctionDeclaration;\n\n\tinitialise(): void {\n\t\tsuper.initialise();\n\t\tif (this.id !== null) {\n\t\t\tthis.id.variable.isId = true;\n\t\t}\n\t}\n\n\tparseNode(esTreeNode: GenericEsTreeNode): void {\n\t\tif (esTreeNode.id !== null) {\n\t\t\tthis.id = new Identifier(\n\t\t\t\tesTreeNode.id,\n\t\t\t\tthis,\n\t\t\t\tthis.scope.parent as ChildScope\n\t\t\t) as IdentifierWithVariable;\n\t\t}\n\t\tsuper.parseNode(esTreeNode);\n\t}\n}\n","import type MagicString from 'magic-string';\nimport {\n\tfindFirstOccurrenceOutsideComment,\n\tfindNonWhiteSpace,\n\ttype NodeRenderOptions,\n\ttype RenderOptions\n} from '../../utils/r