getObjectEntity().getLiteralValueAtPath(path, recursionTracker, origin);\n\t}\n\n\tgetReturnExpressionWhenCalledAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteractionCalled,\n\t\trecursionTracker: PathTracker,\n\t\torigin: DeoptimizableEntity\n\t): ExpressionEntity {\n\t\treturn this.getObjectEntity().getReturnExpressionWhenCalledAtPath(\n\t\t\tpath,\n\t\t\tinteraction,\n\t\t\trecursionTracker,\n\t\t\torigin\n\t\t);\n\t}\n\n\thasEffectsOnInteractionAtPath(\n\t\tpath: ObjectPath,\n\t\tinteraction: NodeInteraction,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\treturn this.getObjectEntity().hasEffectsOnInteractionAtPath(path, interaction, context);\n\t}\n\n\tprotected applyDeoptimizations(): void {\n\t\tthis.deoptimized = true;\n\t\tlet hasSpread = false;\n\t\tfor (let index = 0; index < this.elements.length; index++) {\n\t\t\tconst element = this.elements[index];\n\t\t\tif (element) {\n\t\t\t\tif (hasSpread || element instanceof SpreadElement) {\n\t\t\t\t\thasSpread = true;\n\t\t\t\t\telement.deoptimizePath(UNKNOWN_PATH);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tthis.context.requestTreeshakingPass();\n\t}\n\n\tprivate getObjectEntity(): ObjectEntity {\n\t\tif (this.objectEntity !== null) {\n\t\t\treturn this.objectEntity;\n\t\t}\n\t\tconst properties: ObjectProperty[] = [\n\t\t\t{ key: 'length', kind: 'init', property: UNKNOWN_LITERAL_NUMBER }\n\t\t];\n\t\tlet hasSpread = false;\n\t\tfor (let index = 0; index < this.elements.length; index++) {\n\t\t\tconst element = this.elements[index];\n\t\t\tif (hasSpread || element instanceof SpreadElement) {\n\t\t\t\tif (element) {\n\t\t\t\t\thasSpread = true;\n\t\t\t\t\tproperties.unshift({ key: UnknownInteger, kind: 'init', property: element });\n\t\t\t\t}\n\t\t\t} else if (!element) {\n\t\t\t\tproperties.push({ key: String(index), kind: 'init', property: UNDEFINED_EXPRESSION });\n\t\t\t} else {\n\t\t\t\tproperties.push({ key: String(index), kind: 'init', property: element });\n\t\t\t}\n\t\t}\n\t\treturn (this.objectEntity = new ObjectEntity(properties, ARRAY_PROTOTYPE));\n\t}\n}\n","import type { HasEffectsContext } from '../ExecutionContext';\nimport { NodeInteractionAssigned } from '../NodeInteractions';\nimport { EMPTY_PATH, type ObjectPath } from '../utils/PathTracker';\nimport type LocalVariable from '../variables/LocalVariable';\nimport type Variable from '../variables/Variable';\nimport type * as NodeType from './NodeType';\nimport { UNKNOWN_EXPRESSION } from './shared/Expression';\nimport { NodeBase } from './shared/Node';\nimport type { PatternNode } from './shared/Pattern';\n\nexport default class ArrayPattern extends NodeBase implements PatternNode {\n\tdeclare elements: (PatternNode | null)[];\n\tdeclare type: NodeType.tArrayPattern;\n\n\taddExportedVariables(\n\t\tvariables: readonly Variable[],\n\t\texportNamesByVariable: ReadonlyMap<Variable, readonly string[]>\n\t): void {\n\t\tfor (const element of this.elements) {\n\t\t\telement?.addExportedVariables(variables, exportNamesByVariable);\n\t\t}\n\t}\n\n\tdeclare(kind: string): LocalVariable[] {\n\t\tconst variables: LocalVariable[] = [];\n\t\tfor (const element of this.elements) {\n\t\t\tif (element !== null) {\n\t\t\t\tvariables.push(...element.declare(kind, UNKNOWN_EXPRESSION));\n\t\t\t}\n\t\t}\n\t\treturn variables;\n\t}\n\n\t// Patterns can only be deoptimized at the empty path at the moment\n\tdeoptimizePath(): void {\n\t\tfor (const element of this.elements) {\n\t\t\telement?.deoptimizePath(EMPTY_PATH);\n\t\t}\n\t}\n\n\t// Patterns are only checked at the emtpy path at the moment\n\thasEffectsOnInteractionAtPath(\n\t\t_path: ObjectPath,\n\t\tinteraction: NodeInteractionAssigned,\n\t\tcontext: HasEffectsContext\n\t): boolean {\n\t\tfor (const element of this.elements) {\n\t\t\tif (element?.hasEffectsOnInteractionAtPath(EMPTY_PATH, interaction, context)) return true;\n\t\t}\n\t\treturn false;\n\t}\n\n\tmarkDeclarationReached(): void {\n\t\tfor (const element of this.elements) {\n\t\t\telement?.markDeclarationRe