n\t\t\t);\n\t\t\tconst lastSegment = filteredLine[filteredLine.length - 1];\n\t\t\tfor (const segment of filteredLine) {\n\t\t\t\tif (segment[0] >= location.column || segment === lastSegment) {\n\t\t\t\t\tlocation = {\n\t\t\t\t\t\tcolumn: segment[3],\n\t\t\t\t\t\tline: segment[2] + 1\n\t\t\t\t\t};\n\t\t\t\t\tcontinue traceSourcemap;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tthrow new Error(\"Can't resolve original location of error.\");\n\t}\n\treturn location;\n}\n","export default function removeJsExtension(name: string): string {\n\treturn name.endsWith('.js') ? name.slice(0, -3) : name;\n}\n","import type { NormalizedOutputOptions } from '../../rollup/types';\nimport removeJsExtension from './removeJsExtension';\n\nexport default function getCompleteAmdId(\n\toptions: NormalizedOutputOptions['amd'],\n\tchunkId: string\n): string {\n\tif (options.autoId) {\n\t\treturn `${options.basePath ? options.basePath + '/' : ''}${removeJsExtension(chunkId)}`;\n\t}\n\n\treturn options.id || '';\n}\n","import type { ChunkDependencies, ChunkExports } from '../../Chunk';\nimport type { GetInterop } from '../../rollup/types';\nimport type { GenerateCodeSnippets } from '../../utils/generateCodeSnippets';\nimport {\n\tdefaultInteropHelpersByInteropType,\n\tgetToStringTagValue,\n\tisDefaultAProperty,\n\tnamespaceInteropHelpersByInteropType\n} from '../../utils/interopHelpers';\n\nexport function getExportBlock(\n\texports: ChunkExports,\n\tdependencies: ChunkDependencies,\n\tnamedExportsMode: boolean,\n\tinterop: GetInterop,\n\tsnippets: GenerateCodeSnippets,\n\tt: string,\n\texternalLiveBindings: boolean,\n\tmechanism = 'return '\n): string {\n\tconst { _, cnst, getDirectReturnFunction, getFunctionIntro, getPropertyAccess, n, s } = snippets;\n\tif (!namedExportsMode) {\n\t\treturn `${n}${n}${mechanism}${getSingleDefaultExport(\n\t\t\texports,\n\t\t\tdependencies,\n\t\t\tinterop,\n\t\t\texternalLiveBindings,\n\t\t\tgetPropertyAccess\n\t\t)};`;\n\t}\n\n\tlet exportBlock = '';\n\n\tfor (const 